import random

import pytest


def make_ids(n: int, seed: int) -> list[int]:
    """Return n distinct record ids, reproducible for a given seed.

    Uses a private random.Random(seed) instance, so the result does not
    depend on or modify global random state. Same n and seed always yield
    the same list. Raises ValueError if n is negative.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    rng = random.Random(seed)
    return rng.sample(range(1, 2**31), n)


def test_make_ids_length() -> None:
    assert len(make_ids(10, seed=1)) == 10


def test_make_ids_zero() -> None:
    assert make_ids(0, seed=1) == []


def test_make_ids_distinct() -> None:
    ids = make_ids(1000, seed=7)
    assert len(set(ids)) == 1000


def test_make_ids_deterministic() -> None:
    assert make_ids(25, seed=42) == make_ids(25, seed=42)


def test_make_ids_seed_changes_output() -> None:
    assert make_ids(25, seed=1) != make_ids(25, seed=2)


def test_make_ids_all_ints() -> None:
    assert all(isinstance(i, int) for i in make_ids(5, seed=3))


def test_make_ids_negative_n_raises() -> None:
    with pytest.raises(ValueError):
        make_ids(-1, seed=0)
